{
  "name": "opencode-asyntai",
  "version": "1.0.0",
  "description": "OpenCode plugin for Asyntai, the AI support agent for your website. Adds the Asyntai MCP server so OpenCode can manage your agent's knowledge base, instructions, conversations and leads.",
  "type": "module",
  "main": "./index.js",
  "exports": {
    ".": "./index.js",
    "./server": "./index.js"
  },
  "oc-plugin": [
    "server"
  ],
  "files": [
    "index.js",
    "skills/",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mcp",
    "ai",
    "chatbot",
    "customer-support",
    "asyntai"
  ],
  "homepage": "https://asyntai.com/documentation/integrations/opencode/",
  "bugs": {
    "url": "https://github.com/asyntai/opencode-asyntai/issues",
    "email": "hello@asyntai.com"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/asyntai/opencode-asyntai.git"
  },
  "author": "Asyntai <hello@asyntai.com> (https://asyntai.com)",
  "license": "MIT",
  "engines": {
    "node": ">=18.0"
  },
  "scripts": {
    "test": "node --test tests/plugin.test.js"
  }
}
